(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-235":{scenario:{company:"Tuyết Sơn Cold Chain",supervisor:{name:"Mai Đức Thắng",role:{vi:"Trưởng phòng Đảm bảo Chất lượng Chuỗi lạnh",en:"Cold Chain QA Manager"}},ref_code:"CC-7152",title:{vi:"Đúng nhiệt độ. Đúng dữ liệu. Đúng quyết định.",en:"Right temperature. Right data. Right decision."},brief:{vi:"Container lạnh CC-7152 chở 22 tấn cá tra phi lê đông lạnh từ kho Cần Thơ đến cảng Cát Lái, nhiệt độ cài đặt -20°C, ngưỡng cảnh báo -15°C. Logger ghi mỗi 5 phút; trên hành trình có 3 đợt vượt ngưỡng do máy phát mất điện. Nhiệt độ lõi đo khi nhận là -16,5°C. Đối chiếu biên bản bàn giao nháp với hồ sơ đã duyệt, sửa quyết định xử lý lô và tổng thời gian vượt ngưỡng (phút), rồi lập báo cáo có căn cứ.",en:"Reefer container CC-7152 carries 22 tonnes of frozen pangasius fillets from a Can Tho cold store to Cat Lai port, setpoint -20°C, alarm threshold -15°C. The logger records every 5 minutes; the trip had 3 excursions caused by genset power loss. Core temperature at receipt was -16.5°C. Compare the draft handover record with the approved file, correct the lot disposition and the total excursion time (minutes), then write an evidence-based report."},reference_title:{vi:"Hồ sơ nhiệt độ & quy trình sai lệch đã duyệt · CC-7152",en:"Approved temperature record & excursion procedure · CC-7152"},fields:[{id:"DISPOSITION",label:{vi:"Quyết định xử lý lô",en:"Lot disposition"},initial:"RELEASE",expected:"QUARANTINE",choices:["RELEASE","QUARANTINE","REJECT"],reference:"Quy trình xử lý sai lệch nhiệt độ",ref_value:{vi:"Vượt -15°C cộng dồn trên 60 phút: cách ly chờ QA; lõi trên -12°C: loại bỏ",en:"Above -15°C for over 60 cumulative minutes: quarantine for QA; core above -12°C: reject"},hint:{vi:"Quyết định dựa trên tổng thời gian vượt ngưỡng cộng dồn và nhiệt độ lõi, không dựa vào đợt dài nhất.",en:"Decide on cumulative excursion time and core temperature, not on the longest single event."}},{id:"EXC_MIN",label:{vi:"Tổng thời gian vượt ngưỡng (phút)",en:"Total excursion time (minutes)"},initial:"45",expected:"115",reference:"Báo cáo logger hành trình",ref_value:{vi:"Số bản ghi trên -15°C: đợt 1 có 9, đợt 2 có 6, đợt 3 có 8; chu kỳ ghi 5 phút",en:"Readings above -15°C: event 1 has 9, event 2 has 6, event 3 has 8; logging interval 5 minutes"},hint:{vi:"Cộng dồn mọi đợt vượt ngưỡng trên toàn hành trình rồi nhân với chu kỳ ghi.",en:"Add up every excursion over the whole trip, then multiply by the logging interval."}}],sop32:{vi:"Thời gian vượt ngưỡng = tổng số bản ghi vượt ngưỡng của mọi đợt trong hành trình x chu kỳ ghi của logger; so tổng này với giới hạn trong quy trình xử lý sai lệch.",en:"Excursion time = total readings above the threshold across all events of the trip x logger interval; compare this total with the limit in the excursion procedure."},context:{label:"CCMS / CC-7152",metrics:[{label:{vi:"Nhiệt độ cài đặt",en:"Setpoint"},value:"-20°C"},{label:{vi:"Ngưỡng cảnh báo",en:"Alarm threshold"},value:"-15°C"},{label:{vi:"Nhiệt độ lõi khi nhận",en:"Core temperature at receipt"},value:"-16.5°C"}]},crisis:{vi:"Kinh doanh nhắn: “Tàu chạy tối nay, khách đang chờ. Cắt đoạn dữ liệu logger, chỉ in báo cáo đợt 45 phút rồi cho xuất, đừng cách ly làm gì cho lỡ chuyến.”",en:"Sales messages you: “The vessel sails tonight and the customer is waiting. Cut the logger data, print only the 45-minute event and release it, don't quarantine and miss the sailing.”"},options:{safe:{vi:"Không chỉnh sửa dữ liệu logger; cách ly lô, báo Trưởng phòng QA và khách theo thỏa thuận; đề xuất đo lõi, lấy mẫu đánh giá nhanh và chuẩn bị đổi chuyến nếu cần.",en:"Do not alter logger data; quarantine the lot, inform the QA manager and the customer as agreed, and propose core checks, rapid sampling and a rebooking if needed."},shortcut:{vi:"Cắt bớt dữ liệu logger, in báo cáo đợt 45 phút và cho xuất lô kịp tàu.",en:"Trim the logger data, print the 45-minute event only and release the lot for the sailing."},wait:{vi:"Để container chờ ở bãi, không cập nhật và không báo QA cho đến khi tàu đi.",en:"Leave the container in the yard, update nothing and tell QA nothing until the vessel leaves."}},questions:{vi:["Vì sao lô CC-7152 phải QUARANTINE thay vì RELEASE? Dữ liệu logger nào chứng minh?","Trình bày cách tính tổng thời gian vượt ngưỡng và rủi ro an toàn thực phẩm, pháp lý nếu chỉnh sửa dữ liệu logger."],en:["Why must lot CC-7152 go to QUARANTINE instead of RELEASE? Which logger data proves it?","Explain how you calculated total excursion time and the food safety and legal risks of altering logger data."]},hints:{vi:["Đặt biên bản nháp cạnh quy trình xử lý sai lệch, đánh dấu dòng quyết định đang dựa vào một đợt.","Cộng số bản ghi vượt ngưỡng của cả ba đợt rồi nhân chu kỳ ghi theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dữ liệu nhiệt độ là bằng chứng gốc, mọi áp lực sửa hoặc cắt dữ liệu phải báo cáo."],en:["Place the draft record next to the excursion procedure and flag the decision based on a single event.","Add the readings above threshold from all three events and multiply by the interval per SOP 3.2.","Re-read SOP 4.2: temperature data is original evidence; any pressure to edit or cut it must be escalated."]}},learning:{summary:{vi:"Chuyên viên logistics chuỗi lạnh bảo đảm thực phẩm đông lạnh, hàng mát và dược phẩm được bảo quản, vận chuyển trong dải nhiệt độ yêu cầu từ kho đến điểm nhận. Công việc gồm lập kế hoạch thiết bị lạnh, kiểm tra trước chuyến, giám sát logger, xử lý sai lệch nhiệt độ và lưu hồ sơ truy xuất. Yêu cầu cốt lõi là hiểu an toàn thực phẩm, quy trình kiểm soát nhiệt độ và tôn trọng tuyệt đối dữ liệu gốc.",en:"A cold chain logistics specialist ensures that frozen food, chilled goods and pharmaceuticals are stored and moved within their required temperature range from warehouse to consignee. The work covers planning refrigerated equipment, pre-trip inspections, logger monitoring, handling temperature excursions and keeping traceability records. The core requirements are food safety knowledge, temperature control discipline and absolute respect for original data."},responsibilities:{vi:["Lập kế hoạch xe lạnh, container lạnh và kho lạnh theo loại hàng, dải nhiệt độ và thời gian hành trình.","Kiểm tra trước chuyến (PTI), cài đặt nhiệt độ, làm lạnh trước thiết bị và kiểm tra logger đã hiệu chuẩn.","Giám sát nhiệt độ theo thời gian thực, xử lý cảnh báo, sự cố mất điện và hỏng máy lạnh.","Đánh giá sai lệch nhiệt độ, cách ly lô và phối hợp QA quyết định giải phóng hoặc loại bỏ.","Lưu hồ sơ nhiệt độ, biên bản bàn giao và báo cáo truy xuất cho khách hàng, cơ quan chức năng."],en:["Plan reefer trucks, reefer containers and cold stores by product, temperature range and trip time.","Run pre-trip inspections (PTI), set temperatures, pre-cool equipment and check calibrated loggers.","Monitor temperatures in real time and handle alarms, power loss and refrigeration failures.","Assess excursions, quarantine lots and work with QA on release or rejection.","Keep temperature records and handover reports and provide traceability to customers and authorities."]},competencies:[{name:{vi:"Kiểm soát nhiệt độ",en:"Temperature control"},desc:{vi:"Nắm dải nhiệt độ của từng nhóm hàng và cách xếp hàng để không khí lạnh lưu thông.",en:"Know each product group's range and how to stow so that cold air circulates."}},{name:{vi:"Phân tích dữ liệu logger",en:"Logger data analysis"},desc:{vi:"Đọc đường cong nhiệt độ, tính thời gian vượt ngưỡng cộng dồn và nhận diện nguyên nhân.",en:"Read temperature curves, compute cumulative excursion time and identify causes."}},{name:{vi:"Quản lý sai lệch",en:"Excursion management"},desc:{vi:"Cách ly, điều tra, đánh giá tác động và đề xuất hành động khắc phục, phòng ngừa (CAPA).",en:"Quarantine, investigate, assess impact and propose corrective and preventive actions (CAPA)."}},{name:{vi:"An toàn thực phẩm",en:"Food safety"},desc:{vi:"Áp dụng HACCP, vệ sinh thiết bị và kiểm soát nhiễm chéo trong vận chuyển.",en:"Apply HACCP, equipment hygiene and cross-contamination control in transport."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Giữ dữ liệu nhiệt độ nguyên vẹn, đầy đủ, truy xuất được; từ chối chỉnh sửa trái phép.",en:"Keep temperature data complete, unaltered and traceable; refuse unauthorized edits."}}],knowledge:{vi:["Luật An toàn thực phẩm 2010 (số 55/2010/QH12) và trách nhiệm bảo quản, vận chuyển thực phẩm.","Hệ thống HACCP và các nguyên tắc chung về vệ sinh thực phẩm của Codex Alimentarius.","Dải nhiệt độ phổ biến: hàng đông lạnh từ -18°C trở xuống, hàng mát khoảng 0-5°C, đa số vắc xin 2-8°C.","Thực hành tốt bảo quản và phân phối (GSP, GDP) đối với dược phẩm, vắc xin cần chuỗi lạnh.","Hiệp định ATP của Liên Hợp Quốc về thiết bị vận chuyển thực phẩm dễ hư hỏng.","Hiệu chuẩn thiết bị đo nhiệt độ, bố trí logger và kiểm tra trước chuyến (PTI) container lạnh."],en:["Food Safety Law 2010 (No. 55/2010/QH12) and duties for storing and transporting food.","HACCP and the Codex Alimentarius general principles of food hygiene.","Common ranges: frozen goods at -18°C or below, chilled goods about 0-5°C, most vaccines 2-8°C.","Good storage and distribution practices (GSP, GDP) for cold chain medicines and vaccines.","The UN ATP Agreement on equipment for carrying perishable foodstuffs.","Calibration of temperature instruments, logger placement and reefer pre-trip inspection (PTI)."]},tools:["Data logger nhiệt độ và phần mềm đọc dữ liệu","Hệ thống giám sát nhiệt độ từ xa (IoT)","Nhiệt kế đo lõi đã hiệu chuẩn","Bộ điều khiển máy lạnh container","Hệ thống quản lý kho lạnh (WMS)"],kpis:{vi:["Số sai lệch nhiệt độ trên 100 chuyến.","Tỷ lệ lô bị loại bỏ do hỏng chuỗi lạnh (mục tiêu bằng 0).","Tỷ lệ chuyến có đầy đủ dữ liệu logger, truy xuất được.","Thời gian phản hồi cảnh báo nhiệt độ."],en:["Temperature excursions per 100 trips.","Share of lots rejected due to cold chain failure (target zero).","Share of trips with complete, traceable logger data.","Response time to temperature alarms."]},day:[{time:"06:00",vi:"Kiểm tra PTI container lạnh, làm lạnh trước thùng xe và cài đặt logger cho chuyến sáng.",en:"Run reefer PTIs, pre-cool truck bodies and set loggers for morning trips."},{time:"08:30",vi:"Giám sát xếp hàng tại cửa kho lạnh, kiểm tra nhiệt độ lõi và thời gian mở cửa.",en:"Supervise loading at the cold store dock, check core temperatures and door-open time."},{time:"11:00",vi:"Theo dõi bảng giám sát từ xa, xử lý cảnh báo vượt ngưỡng trên các tuyến.",en:"Watch the remote monitoring dashboard and handle threshold alarms on all routes."},{time:"14:00",vi:"Rà soát dữ liệu logger chuyến đã về, lập báo cáo sai lệch và đề xuất CAPA.",en:"Review logger data from returned trips, write excursion reports and propose CAPA."},{time:"17:00",vi:"Bàn giao ca, lưu hồ sơ nhiệt độ và cập nhật trạng thái cách ly, giải phóng lô.",en:"Hand over the shift, file temperature records and update quarantine and release status."}],mistakes:{vi:["Chỉ xét đợt vượt ngưỡng dài nhất, bỏ qua thời gian vượt ngưỡng cộng dồn cả hành trình.","Cho xe lạnh nhận hàng khi chưa làm lạnh trước thùng hoặc xếp hàng chặn luồng gió.","Cắt, sửa dữ liệu logger hoặc giải phóng lô sai lệch để kịp chuyến, gây rủi ro an toàn thực phẩm."],en:["Looking only at the longest excursion and ignoring cumulative time over the whole trip.","Loading a reefer before pre-cooling or stowing cargo that blocks the airflow.","Cutting or editing logger data or releasing a deviating lot to make a sailing, risking food safety."]},career:[{vi:"Nhân viên giám sát chuỗi lạnh",en:"Cold chain monitoring assistant"},{vi:"Chuyên viên logistics chuỗi lạnh",en:"Cold chain logistics specialist"},{vi:"Trưởng nhóm đảm bảo chất lượng chuỗi lạnh",en:"Cold chain QA lead"},{vi:"Quản lý vận hành chuỗi lạnh",en:"Cold chain operations manager"}],glossary:[{term:"Excursion",vi:"Sai lệch nhiệt độ: khoảng thời gian hàng nằm ngoài dải nhiệt độ cho phép.",en:"Temperature excursion: a period when goods are outside the allowed range."},{term:"PTI",vi:"Kiểm tra trước chuyến đối với container lạnh: máy lạnh, cảm biến, độ kín và vệ sinh.",en:"Pre-trip inspection of a reefer: refrigeration unit, sensors, seals and cleanliness."},{term:"Data logger",vi:"Thiết bị tự ghi nhiệt độ theo chu kỳ, là bằng chứng gốc của hành trình.",en:"Device that records temperature at set intervals and serves as original trip evidence."},{term:"Pre-cooling",vi:"Làm lạnh trước thùng xe hoặc container đến nhiệt độ cài đặt trước khi xếp hàng.",en:"Cooling the truck body or container to setpoint before loading."},{term:"Quarantine",vi:"Cách ly lô hàng, tạm dừng sử dụng hoặc xuất bán cho đến khi QA đánh giá xong.",en:"Holding a lot from use or sale until QA completes its assessment."}],quiz:[{q:{vi:"Logger ghi mỗi 10 phút, có 4 bản ghi vượt ngưỡng ở đợt 1 và 3 bản ghi ở đợt 2. Tổng thời gian vượt ngưỡng là bao nhiêu?",en:"A logger records every 10 minutes, with 4 readings above threshold in event 1 and 3 in event 2. What is the total excursion time?"},options:{vi:["70 phút","40 phút","30 phút","7 phút"],en:["70 minutes","40 minutes","30 minutes","7 minutes"]},answer:0,explain:{vi:"Cộng dồn 4 + 3 = 7 bản ghi, nhân chu kỳ 10 phút được 70 phút.",en:"Add 4 + 3 = 7 readings and multiply by the 10-minute interval to get 70 minutes."}},{q:{vi:"Dải nhiệt độ bảo quản phổ biến của đa số vắc xin là bao nhiêu?",en:"What is the usual storage range for most vaccines?"},options:{vi:["-25 đến -15°C","15-25°C","2-8°C","0-30°C"],en:["-25 to -15°C","15-25°C","2-8°C","0-30°C"]},answer:2,explain:{vi:"Đa số vắc xin bảo quản 2-8°C; một số loại đặc thù cần đông lạnh sâu theo hướng dẫn nhà sản xuất.",en:"Most vaccines are kept at 2-8°C; some special products need deep-frozen storage per the manufacturer."}},{q:{vi:"Kinh doanh đề nghị cắt dữ liệu logger để lô sai lệch kịp tàu. Bạn làm gì?",en:"Sales asks you to cut logger data so a deviating lot makes the vessel. What do you do?"},options:{vi:["Cắt dữ liệu vì chỉ vượt ngưỡng ngắn","Cho xuất rồi báo QA sau","Chờ tàu đi rồi mới báo","Giữ nguyên dữ liệu, cách ly lô và báo QA, khách hàng"],en:["Cut it since the excursion was short","Release now and tell QA later","Report only after the vessel leaves","Keep the data intact, quarantine the lot and inform QA and the customer"]},answer:3,explain:{vi:"Dữ liệu nhiệt độ là bằng chứng an toàn thực phẩm; chỉnh sửa là gian lận và có thể gây hại cho người tiêu dùng.",en:"Temperature data is food safety evidence; editing it is fraud and can harm consumers."}},{q:{vi:"Vì sao phải làm lạnh trước thùng xe trước khi xếp hàng đông lạnh?",en:"Why must a truck body be pre-cooled before loading frozen goods?"},options:{vi:["Để tiết kiệm nhiên liệu khi chạy","Vì máy lạnh xe chủ yếu duy trì nhiệt độ, không được thiết kế để hạ nhiệt hàng","Để tăng trọng lượng hàng","Để giảm thời gian thông quan"],en:["To save fuel on the road","Because the unit is built to maintain temperature, not to pull down warm cargo","To increase cargo weight","To shorten customs clearance"]},answer:1,explain:{vi:"Thùng ấm làm hàng tăng nhiệt ngay khi xếp; máy lạnh vận tải chỉ giữ nhiệt độ, không hạ nhiệt nhanh cho hàng.",en:"A warm body heats cargo on loading; transport units hold temperature and are not designed to pull it down."}}],tools_en:["Temperature data logger and reader software","Remote temperature monitoring system (IoT)","Calibrated core probe thermometer","Reefer container controller","Cold storage management system (WMS)"]}}})})(window.KKR);
